// The proposed extension-facing surface (NOT added under M2).
// Descriptor is MCPServer (capability/mcp.ts:15-74) MINUS `_source`:
// core stamps provenance so an extension cannot forge where a server came from.
interface McpServerDescriptor {
	name: string;
	enabled?: boolean;
	timeout?: number;
	command?: string;   // stdio
	args?: string[];
	env?: Record<string, string>;
	cwd?: string;
	url?: string;      // http | sse
	headers?: Record<string, string>;
	transport?: "stdio" | "sse" | "http";
	auth?: MCPServer["auth"];
	oauth?: MCPServer["oauth"];
}

// On ExtensionAPI (extensions/types.ts:1256), beside the other register* methods
// (:1347 registerTool, :1411 registerCommand, :1430 registerFlag):
registerMcpServer(descriptor: McpServerDescriptor): void;

// Core side — every step below already exists. The build is a producer plus a map.
class McpServerRegistry {
	#byExtension = new Map<string, Set<string>>();  // extensionId -> server names

	async #connect(extensionId: string, source: SourceMeta, descriptor: McpServerDescriptor) {
		const config: MCPServerConfig = toLegacyConfig({ ...descriptor, _source: source });
		// Already public, already incremental, already stamps sources (:690-696).
		await this.#manager.connectServers({ [descriptor.name]: config }, { [descriptor.name]: source });
		this.#byExtension.get(extensionId)?.add(descriptor.name);
	}

	// Teardown. Ownership is matched via mcpServerName, NEVER a sanitized
	// mcp__<name>_ prefix — see the comment at manager.ts:937-941
	// ('atlassian' vs 'atlassian:atlassian').
	async #disconnectAll(extensionId: string) {
		for (const name of this.#byExtension.get(extensionId) ?? []) {
			await this.#manager.disconnectServer(name);   // manager.ts:1242
		}
		this.#byExtension.delete(extensionId);
	}
}

